from ta_logcollector.plugins.__egate_interface import EgateInterface
from ta_logcollector.plugins.__sosreport import collect_sos_report
from ta_logcollector.settings import SERVER_HOST
from ta_logcollector.logger import get_net_logger


class iphy(EgateInterface):
    def __init__(self, log_host, log_port, configuration, **kwargs):
        # type: (str, int, dict, Optional[Dict[str, Any]]) -> None
        """
        Plugin to gather logs from EPC and I-PHY (WTS)
        :param log_host: IP address of logger host
        :param log_port: port of logger host
        :param configuration:
        """
        super(iphy, self).__init__(configuration, **kwargs)
        self._logger = get_net_logger(log_host, log_port, "iphy_{}".format(SERVER_HOST))
        self.__user_proxy_config = None

    def start(self):
        # type: () -> None
        """Method prepare and start collecting IPhy logs."""
        self._logger.debug("configuration = {}".format(self._configuration))
        if not self._configuration.get("connect_on_start", True):
            # for robot interface it is False, so we don't change config
            return
        self._back_up_proxy_log_config()
        self._set_epcsim_config()

    def stop(self):
        # type: () -> None
        """Method collect and store IPhy logs."""
        if self._backup_values:
            self._restore_proxy_log_config()
        if self._configuration["sosreport"]:
            collect_sos_report("iphy", self._log_dir, self._logger)

    @property
    def _user_proxy_config(self):
        if self.__user_proxy_config is None:
            if "proxy" in self._configuration:
                self.__user_proxy_config = list(
                    filter(lambda d: self._configuration["proxy"][d], self._configuration["proxy"])
                )
            else:
                self.__user_proxy_config = []
        return self.__user_proxy_config

    def _set_proxy_log(self):
        # type: () -> None
        """Set's proxy_log for ePCSim via EGATE console"""
        proxy_params = {name.upper(): "debug" for name in self._user_proxy_config}
        self._logger.debug("proxy_log params = {}".format(proxy_params))
        if proxy_params:
            self._execute_egate_command(cmd="proxy_log", **proxy_params)

    def _set_epcsim_config(self):
        # type: () -> None
        """Set's provided IPHY config via EGATE console"""
        self._set_proxy_log()

    def _back_up_proxy_log(self):
        if not self._user_proxy_config:
            return
        if not self._check_egate_connectivity(self.egate_id):
            self._logger.debug("Egate not responding. '{} {}' will not be invoked".format("proxy log", ""))
            return
        self._logger.debug("Back up proxy_log ongoing")
        try:
            cmd = self._egate_cmd_parser.get_command("proxy_log")()
            output = cmd.execute_and_parse(egate_id=self.egate_id)
            bitmap_dict = {}
            for enb_id, enb_data in output.items():
                bitmap_dict[enb_id] = {}
                for cell_id, cell_data in enb_data.items():
                    bitmap_dict[enb_id][cell_id] = dict(
                        zip(["debug", "info", "warning", "error"], cell_data["bitmap"].split())
                    )
            return bitmap_dict
        except Exception as err:
            self._logger.exception(err)

    def _back_up_proxy_log_config(self):
        self._backup_values.update({"masks": self._back_up_proxy_log()})
        self._logger.debug("backup_values = {}".format(self._backup_values))

    def _restore_proxy_log_config(self):
        if not list(self._user_proxy_config):
            return
        for enb_id, enb_data in self._backup_values["masks"].items():
            for cell_id, cell_data in enb_data.items():
                self._execute_egate_command(
                    "proxy_log",
                    enb=enb_id,
                    cell=cell_id,
                    debug_mask=cell_data["debug"],
                    info_mask=cell_data["info"],
                    warn_mask=cell_data["warning"],
                    error_mask=cell_data["error"],
                )


